-- Fakt kartochkalarining ruscha matni — 10-partiya: Zardusht, Kanishka, Muqanna.

-- ===== Zardusht =====
UPDATE fact_cards SET topic_ru = 'Кто я?', question_ru = 'Основателем какой религии был Заратуштра?', fact_ru = 'Я Заратуштра — основатель зороастризма; моё имя в разных языках произносят также как Зардушт и Зороастр.' WHERE id = 491;
UPDATE fact_cards SET topic_ru = 'Время моей жизни', question_ru = 'В какое время жил Заратуштра?', fact_ru = 'Я историческое лицо, живший в первой половине I тысячелетия до нашей эры.' WHERE id = 492;
UPDATE fact_cards SET topic_ru = 'Связь с Хорезмом', question_ru = 'Где, по мнению учёных, возникли древнейшие части «Авесты»?', fact_ru = 'Многие учёные считают, что древнейшие части «Авесты» возникли в Хорезмском оазисе.' WHERE id = 493;
UPDATE fact_cards SET topic_ru = 'Пророчество', question_ru = 'Согласно преданию, в каком возрасте Заратуштра стал пророком?', fact_ru = 'Согласно преданию, в 30 лет я стал пророком нового вероучения; слово «пророк» означает «возвещающий о добрых деяниях».' WHERE id = 494;
UPDATE fact_cards SET topic_ru = 'Главное правило', question_ru = 'Каковы три главных правила учения Заратуштры?', fact_ru = 'Главных правил моего учения три: благая мысль, благое слово и благое дело.' WHERE id = 495;
UPDATE fact_cards SET topic_ru = 'Священные стихии', question_ru = 'Какие стихии считались священными в зороастризме?', fact_ru = 'В нашей вере священными считались огонь, вода, земля и воздух.' WHERE id = 496;
UPDATE fact_cards SET topic_ru = 'Книга «Авеста»', question_ru = 'Что означает название «Авеста»?', fact_ru = 'После моей смерти мои проповеди, гимны и молитвы были собраны в книгу «Авеста»; это название означает «твёрдо установленные законы и правила».' WHERE id = 497;
UPDATE fact_cards SET topic_ru = 'История «Авесты»', question_ru = 'В скольких книгах собраны тексты «Авесты»?', fact_ru = 'Первая часть «Авесты» появилась в IX–VIII веках до нашей эры, позже все тексты были собраны в 21 книгу.' WHERE id = 498;
UPDATE fact_cards SET topic_ru = 'В глазах греков', question_ru = 'Каким именем греки называли Заратуштру?', fact_ru = 'Греки знали меня прежде всего как мудреца и звездочёта, потому и называли моё имя «Зороастр».' WHERE id = 499;
UPDATE fact_cards SET topic_ru = 'Корни Навруза', question_ru = 'К какому времени восходят корни праздника Навруз?', fact_ru = 'Корни праздника Навруз восходят как раз к этой древней поре.' WHERE id = 500;
UPDATE fact_cards SET topic_ru = 'Гимны «Гаты»', question_ru = 'Как называется древнейшая часть «Авесты», приписываемая Заратуштре?', fact_ru = 'Древнейшая часть «Авесты» называется «Гаты». Эти гимны приписываются непосредственно мне.' WHERE id = 1821;
UPDATE fact_cards SET topic_ru = 'Ахура Мазда', question_ru = 'Кто есть бог добра, прославляемый в учении Заратуштры?', fact_ru = 'В моём учении прославляется бог добра — Ахура Мазда. Это имя означает «мудрый владыка».' WHERE id = 1822;
UPDATE fact_cards SET topic_ru = 'Борьба двух сил', question_ru = 'Какие две силы, согласно учению Заратуштры, борются в мире?', fact_ru = 'Согласно моему учению, в мире идёт борьба между добром и злом. Я учил, что каждый человек должен встать на сторону добра.' WHERE id = 1823;
UPDATE fact_cards SET topic_ru = 'Храмы огня', question_ru = 'Как называлось место поклонения в религии Заратуштры?', fact_ru = 'Место, где молились мои последователи, называлось храмом огня. В храмах огня священное пламя никогда не гасили.' WHERE id = 1824;
UPDATE fact_cards SET topic_ru = 'Достоинство труда', question_ru = 'Какие дела считались благими в учении Заратуштры?', fact_ru = 'В моём учении честный труд возвеличен: человек, вспахавший землю, вырастивший сад и выходивший скот, считается совершившим благое дело.' WHERE id = 1825;
UPDATE fact_cards SET topic_ru = '2700-летие «Авесты»', question_ru = 'Когда в Узбекистане отмечалось 2700-летие «Авесты» — книги Заратуштры?', fact_ru = 'В 2001 году в Узбекистане широко отмечалось 2700-летие создания «Авесты». В городе Ургенч был возведён мемориальный комплекс «Авеста».' WHERE id = 1826;
UPDATE fact_cards SET topic_ru = 'Свидетельство Беруни', question_ru = 'Какой великий учёный оставил сведения о Заратуштре в своих трудах?', fact_ru = 'Великий учёный Абу Райхан Беруни оставил в своих трудах ценные сведения обо мне и моём учении.' WHERE id = 1827;

-- ===== Kanishka =====
UPDATE fact_cards SET topic_ru = 'Кто я?', question_ru = 'Правителем какого царства был Канишка?', fact_ru = 'Я Канишка — правитель Кушанского царства; в пору моей державы юг нынешнего Узбекистана тоже входил в моё государство.' WHERE id = 511;
UPDATE fact_cards SET topic_ru = 'Пора державы', question_ru = 'В каких веках правило Кушанское государство?', fact_ru = 'Кушанское государство правило с I по III век нашей эры; в моё время оно достигло вершины своего расцвета.' WHERE id = 512;
UPDATE fact_cards SET topic_ru = 'Столица', question_ru = 'В какой город Канишка перенёс столицу?', fact_ru = 'Я перенёс столицу из Бактрии в город Пешавар (территория нынешнего Пакистана).' WHERE id = 513;
UPDATE fact_cards SET topic_ru = 'Владения державы', question_ru = 'Какие земли входили в состав Кушанского государства?', fact_ru = 'В состав моего государства входили земли Индии, Хотана, Афганистана и вплоть до юга Узбекистана.' WHERE id = 514;
UPDATE fact_cards SET topic_ru = 'В ряду великих держав', question_ru = 'В ряду каких великих держав стояло Кушанское государство?', fact_ru = 'В ряду Рима, Парфии и Китая Кушанское государство тоже стало одним из огромных царств своего времени.' WHERE id = 515;
UPDATE fact_cards SET topic_ru = 'Торговля и посольства', question_ru = 'С какими государствами была налажена торговля во времена Канишки?', fact_ru = 'В моё время строились всё новые города, были налажены торговые и посольские связи с Индией, Китаем и Римской империей.' WHERE id = 516;
UPDATE fact_cards SET topic_ru = 'Буддизм', question_ru = 'Как буддизм пришёл на нашу землю?', fact_ru = 'Благодаря тесным связям с Индией на нашу землю пришёл буддизм и начал распространяться по Средней Азии через Сурхандарьинский оазис.' WHERE id = 517;
UPDATE fact_cards SET topic_ru = 'Термезские святилища', question_ru = 'Какие святилища близ Термеза свидетельствуют о буддизме?', fact_ru = 'Святилища Фаязтепа и Каратепа близ Термеза свидетельствуют о широком распространении буддизма.' WHERE id = 518;
UPDATE fact_cards SET topic_ru = 'Дальверзинтепа', question_ru = 'Где была первая столица Кушанского царства?', fact_ru = 'Дальверзинтепа была первой столицей Кушанского царства; в моё время этот город развился ещё больше.' WHERE id = 519;
UPDATE fact_cards SET topic_ru = 'Монеты', question_ru = 'Из каких металлов чеканили монеты в Кушанском царстве?', fact_ru = 'В Кушанском царстве чеканили монеты из золота, серебра и меди.' WHERE id = 520;
UPDATE fact_cards SET topic_ru = 'Основатель моей династии', question_ru = 'Кто основал Кушанскую династию, к которой принадлежал Канишка?', fact_ru = 'Нашу династию основал Кадфиз I — он объединил племена под началом кушанского рода и создал единое государство.' WHERE id = 1688;
UPDATE fact_cards SET topic_ru = 'Корни моего народа', question_ru = 'На основе каких племён возникло государство Канишки — Кушанское царство?', fact_ru = 'Кушанское государство возникло на основе племён юэчжи; сведения об этом сохранились в древних китайских летописях.' WHERE id = 1689;
UPDATE fact_cards SET topic_ru = 'Рабатакская надпись', question_ru = 'На каком языке написана Рабатакская надпись, дающая сведения о Канишке и его предках?', fact_ru = 'На каменной надписи, найденной в местечке Рабатак в Афганистане, записаны моё имя и перечень моих предков. Надпись сделана на бактрийском языке греческими буквами.' WHERE id = 1690;
UPDATE fact_cards SET topic_ru = 'Искусство Гандхары', question_ru = 'Как называется искусство, расцветшее при Канишке и соединившее греческий и индийский стили?', fact_ru = 'В моё время расцвело искусство Гандхары — в нём соединились греческий и индийский стили и создавались прекрасные статуи.' WHERE id = 1691;
UPDATE fact_cards SET topic_ru = 'Моя статуя в Матхуре', question_ru = 'Откуда происходит знаменитая статуя Канишки с надписью «царь царей»?', fact_ru = 'В индийском городе Матхура была найдена моя каменная статуя. На ней есть надпись: «великий царь, царь царей Канишка».' WHERE id = 1692;
UPDATE fact_cards SET topic_ru = 'Огромная ступа', question_ru = 'Какое огромное сооружение возвёл Канишка в своей столице Пурушапуре?', fact_ru = 'В моей столице Пурушапуре я велел возвести огромную буддийскую ступу. Позже видевшие её путешественники записали своё изумление.' WHERE id = 1693;
UPDATE fact_cards SET topic_ru = 'Собор монахов', question_ru = 'Какое важное собрание в истории буддизма прошло во времена Канишки?', fact_ru = 'Согласно истории буддизма, в моё время был созван большой собор монахов, и священные тексты этой веры были приведены в порядок.' WHERE id = 1694;

-- ===== Muqanna =====
UPDATE fact_cards SET topic_ru = 'Моё настоящее имя', question_ru = 'Каково настоящее имя Муканны?', fact_ru = 'Моё настоящее имя — Хашим ибн Хаким. Я родился в селении Коза близ города Мерв и был ремесленником.' WHERE id = 453;
UPDATE fact_cards SET topic_ru = 'Тайна моего прозвища', question_ru = 'Почему Хашима ибн Хакима назвали «Муканна»?', fact_ru = 'За то, что я закрывал голову и лицо зелёным покрывалом, меня прозвали «Муканна», то есть «Закрытый покрывалом».' WHERE id = 454;
UPDATE fact_cards SET topic_ru = 'Мои знания', question_ru = 'Что написал о Муканне Наршахи?', fact_ru = 'Как пишет историк Наршахи, я был человеком много читавшим и весьма проницательным, изучал науку химии и хорошо знал арабский и персидский языки.' WHERE id = 455;
UPDATE fact_cards SET topic_ru = 'Моя служба в Хорасане', question_ru = 'До какой должности поднялся Муканна в Хорасане?', fact_ru = 'В Хорасане я поднялся от малого войскового начальника до должности визиря.' WHERE id = 456;
UPDATE fact_cards SET topic_ru = 'Восстание «людей в белом»', question_ru = 'В какие годы было восстание «людей в белом»?', fact_ru = 'В 769–783 годах я возглавил большое народное восстание против гнёта арабского халифата. Оттого что мои сторонники носили белые одежды, наше движение вошло в историю как восстание «людей в белом».' WHERE id = 457;
UPDATE fact_cards SET topic_ru = 'Крепость Сом', question_ru = 'Какую крепость Муканна сделал своей ставкой?', fact_ru = 'Своей ставкой я сделал крепость Сом, выстроенную на вершине горы близ Кеша. Вскоре весь Кашкадарьинский оазис перешёл в наши руки.' WHERE id = 458;
UPDATE fact_cards SET topic_ru = 'Расширение движения', question_ru = 'В каких краях разгорелось восстание Муканны?', fact_ru = 'Наше восстание особенно разгорелось в Согде, а также затронуло долину Илака (Ахангаран) и Шаш. В нём участвовали представители разных сословий.' WHERE id = 459;
UPDATE fact_cards SET topic_ru = 'Моё учение', question_ru = 'Какое учение проповедовал Муканна?', fact_ru = 'Я проповедовал учение, основанное на идеях Маздака и призывавшее к общественному равенству и свободной жизни.' WHERE id = 460;
UPDATE fact_cards SET topic_ru = 'Против войск халифа', question_ru = 'Что произошло с войском халифа Мансура в 775 году?', fact_ru = 'В 775 году халиф Мансур послал против нас большую военную силу. В первых столкновениях арабские войска понесли большие потери и отступили к Самарканду.' WHERE id = 461;
UPDATE fact_cards SET topic_ru = 'Исход восстания и память обо мне', question_ru = 'Какие писатели создали произведения о Муканне?', fact_ru = 'В 783 году моя ставка в крепости Сом была взята в долгую осаду, и в том же году я погиб. Память обо мне живёт в литературе: Хамид Алимджан написал драму «Муканна», а Садриддин Айни — историко-литературный очерк «Восстание Муканны».' WHERE id = 462;
UPDATE fact_cards SET topic_ru = 'Символ белых одежд', question_ru = 'Почему сторонники Муканны носили белую одежду?', fact_ru = 'Халифат сделал своим знаменем чёрный цвет. А мои сторонники в знак сопротивления ему носили белоснежные одежды. Потому наше движение и назвали «людьми в белом».' WHERE id = 1730;
UPDATE fact_cards SET topic_ru = 'Причины борьбы', question_ru = 'По какой причине народ объединился вокруг Муканны?', fact_ru = 'Народ был сильно недоволен тяжёлыми податями и гнётом арабского халифата. Потому дехкане и ремесленники объединились вокруг меня.' WHERE id = 1731;
UPDATE fact_cards SET topic_ru = 'Годы борьбы', question_ru = 'Сколько лет длилось восстание Муканны?', fact_ru = 'Восстание под моим началом длилось с 769 по 783 год — почти четырнадцать лет. Это было одно из крупнейших народных восстаний в Мавераннахре.' WHERE id = 1732;
UPDATE fact_cards SET topic_ru = 'Подмога тюркских племён', question_ru = 'Кто пришёл на помощь восставшим Муканны?', fact_ru = 'На помощь нашей борьбе со стороны степи пришли и тюркские племена. Они сражались в рядах восставших против войск халифата.' WHERE id = 1733;
UPDATE fact_cards SET topic_ru = 'Предание о нахшебской луне', question_ru = 'О чём говорится в предании о Муканне «нахшебская луна»?', fact_ru = 'По преданиям, в городе Нахшеб я будто бы показывал луну, поднимавшуюся из колодца. Это предание о «нахшебской луне» веками передавалось из уст в уста.' WHERE id = 1734;
UPDATE fact_cards SET topic_ru = 'В древних книгах', question_ru = 'В каких древних трудах сохранились сведения о Муканне?', fact_ru = 'Сведения обо мне сохранились в древних книгах. Особенно о нашем восстании написано в труде Наршахи «История Бухары» и в трудах Абу Райхана Беруни.' WHERE id = 1735;
UPDATE fact_cards SET topic_ru = 'Я — герой драмы', question_ru = 'Какой поэт написал драму о Муканне в XX веке?', fact_ru = 'Спустя более тысячи лет, в XX веке, поэт Хамид Алимджан написал обо мне драму под названием «Муканна». Так моё имя зазвучало и на театральной сцене.' WHERE id = 1736;
